const raw = $json.output?.[0]?.content?.[0]?.text
  ?? $json.message?.content
  ?? $json.content
  ?? "";

let parsed;
try {
  parsed = typeof raw === "string"
    ? JSON.parse(raw.replace(/```json|```/g, "").trim())
    : raw;
} catch (e) {
  return [{ json: { ...$('Loop Feedback').item.json, valid: false, fail: "unparseable" } }];
}

const item = $('Loop Feedback').item.json;
const allowedThemes = ["pricing","onboarding","reliability_bugs","feature_request",
  "customer_support","performance_speed","ui_ux","documentation","integration","billing","other"];
const allowedSeverity = ["critical","high","medium","low"];
const allowedSentiment = ["positive","neutral","negative","mixed"];

const quote = (parsed.key_quote || "").trim().replace(/^["']|["']$/g, "");

function normalize(s) {
  return (s || "").replace(/['’‘]/g, "").toLowerCase();
}

const validThemes = Array.isArray(parsed.themes)
  ? parsed.themes.filter(t => allowedThemes.includes(t))
  : [];

const checks = {
  quoteIsReal:    quote.length > 0 && normalize(item.raw_text).includes(normalize(quote)),
  themesValid:    validThemes.length > 0 && validThemes.length <= 3,
  severityValid:  allowedSeverity.includes(parsed.severity),
  sentimentValid: allowedSentiment.includes(parsed.sentiment)
};

const failed = Object.entries(checks).filter(([,v]) => !v).map(([k]) => k);

return [{ json: {
  ...item,
  sentiment: parsed.sentiment,
  severity: parsed.severity,
  themes: validThemes,
  key_quote: quote,
  valid: failed.length === 0,
  fail: failed.join(",")
}}];

const rows = $input.all().map(i => i.json);
const cutoff = new Date();
cutoff.setDate(cutoff.getDate() - 7);

const thisWeek = rows.filter(r => new Date(r.submitted_at) >= cutoff);
const lastWeek = rows.filter(r => new Date(r.submitted_at) < cutoff);

function countThemes(set) {
  const counts = {};
  set.forEach(r => (r.themes || []).forEach(t => counts[t] = (counts[t] || 0) + 1));
  return counts;
}

const thisCounts = countThemes(thisWeek);
const lastCounts = countThemes(lastWeek);

const themeTrend = Object.keys(thisCounts).map(theme => ({
  theme,
  count: thisCounts[theme],
  prevCount: lastCounts[theme] || 0,
  delta: thisCounts[theme] - (lastCounts[theme] || 0)
})).sort((a, b) => b.count - a.count);

const sentimentSplit = ["positive","neutral","negative","mixed"].map(s => ({
  sentiment: s,
  count: thisWeek.filter(r => r.sentiment === s).length
}));

const topQuotesByTheme = {};
themeTrend.slice(0, 5).forEach(t => {
  topQuotesByTheme[t.theme] = thisWeek
    .filter(r => (r.themes || []).includes(t.theme))
    .slice(0, 2)
    .map(r => r.key_quote);
});

const criticalItems = thisWeek
  .filter(r => r.severity === 'critical')
  .map(r => ({ customer_name: r.customer_name, quote: r.key_quote }));

return [{ json: {
  weekOf: cutoff.toISOString().slice(0,10),
  totalFeedback: thisWeek.length,
  criticalCount: thisWeek.filter(r => r.severity === 'critical').length,
  criticalItems,
  themeTrend,
  sentimentSplit,
  topQuotesByTheme
}}];

const raw = $json.output?.[0]?.content?.[0]?.text
  ?? $json.message?.content
  ?? $json.content
  ?? "";

const summary = (raw || "").trim();
const data = $('Aggregate Trends').item.json;

const mentionsTotal = summary.includes(String(data.totalFeedback));

const criticalNamesOk = data.criticalCount > 0
  ? (data.criticalItems || []).length > 0 &&
    (data.criticalItems || []).every(c => summary.includes(c.customer_name))
  : true;

const checks = {
  hasSummary:        summary.length > 20 && summary.length < 900,
  totalReferenced:   mentionsTotal,
  criticalNamesReal: criticalNamesOk
};

const failed = Object.entries(checks).filter(([,v]) => !v).map(([k]) => k);

return [{ json: {
  ...data,
  summary,
  valid: failed.length === 0,
  fail: failed.join(",")
}}];
